=== HeroTiefe
/**
 * Tiefen-Ebenen für dunkle Heros (Startseite, Landingpages).
 *
 * Rein dekorativ (aria-hidden), Server-Komponente, keine Hex-Werte:
 * Farben kommen über currentColor bzw. Token-Variablen.
 *
 *  1. Lichtkegel oben rechts (Sonne, sehr dezent) und grünes Bodenlicht
 *  2. Fluchtlinien wie Modulreihen, die zum Horizont laufen
 *  3. Energiefluss-Linien, die einmal einlaufen (ov-linie, stroke-dashoffset)
 *  4. wenige schwebende Lichtpunkte (animate-ov-float, nur transform)
 *
 * Unter prefers-reduced-motion steht alles still im Endzustand.
 * Elternelement braucht `relative isolate overflow-hidden`.
 */
const PUNKTE = [
  { x: 62, y: 22, r: 2.2, d: "-1.2s", o: 0.7 },
  { x: 78, y: 38, r: 1.6, d: "-3.4s", o: 0.55 },
  { x: 88, y: 18, r: 1.4, d: "-5.1s", o: 0.45 },
  { x: 70, y: 58, r: 2, d: "-2.3s", o: 0.5 },
  { x: 94, y: 48, r: 1.2, d: "-4.2s", o: 0.4 },
  { x: 54, y: 70, r: 1.4, d: "-6s", o: 0.35 },
];

export default function HeroTiefe({ className = "" }) {
  return (
    <div aria-hidden="true" className={`pointer-events-none absolute inset-0 -z-10 ${className}`}>
      {/* 1 – Licht */}
      <div
        className="absolute -right-[10%] -top-[30%] h-[80%] w-[60%] rounded-full opacity-70"
        style={{ background: "radial-gradient(closest-side, color-mix(in oklab, var(--color-sun-300) 22%, transparent), transparent)" }}
      />
      <div
        className="absolute -bottom-[35%] left-[10%] h-[70%] w-[70%] rounded-full"
        style={{ background: "radial-gradient(closest-side, color-mix(in oklab, var(--color-ov-500) 26%, transparent), transparent)" }}
      />

      {/* 2 + 3 – Linien (nur ab Tablet, mobil bleibt die Fläche ruhig) */}
      <svg
        viewBox="0 0 100 60"
        preserveAspectRatio="xMidYMid slice"
        className="ov-sofort absolute inset-0 hidden h-full w-full md:block"
      >
        <g className="text-white" stroke="currentColor" strokeWidth="0.08" fill="none" opacity="0.14">
          {Array.from({ length: 9 }, (_, i) => (
            <line key={i} x1={58 + i * 5.5} y1="60" x2={80 + i * 0.6} y2="30" />
          ))}
          {[38, 44, 52].map((y) => (
            <line key={y} x1="50" y1={y} x2="100" y2={y - 2} />
          ))}
        </g>
        <g className="text-ov-300" stroke="currentColor" fill="none" strokeLinecap="round">
          <path d="M 46 58 C 60 50, 66 40, 82 34 S 98 26, 104 22" strokeWidth="0.18" opacity="0.55" pathLength="1" className="ov-linie" style={{ "--ov-delay": "500ms" }} />
          <path d="M 58 62 C 70 52, 76 46, 90 42 S 100 38, 106 36" strokeWidth="0.12" opacity="0.35" pathLength="1" className="ov-linie" style={{ "--ov-delay": "750ms" }} />
        </g>
      </svg>

      {/* 4 – Lichtpunkte */}
      <div className="absolute inset-0 hidden md:block">
        {PUNKTE.map((p, i) => (
          <span
            key={i}
            className="absolute rounded-full bg-ov-300 motion-safe:animate-ov-float"
            style={{
              left: `${p.x}%`,
              top: `${p.y}%`,
              width: `${p.r * 3}px`,
              height: `${p.r * 3}px`,
              opacity: p.o,
              animationDelay: p.d,
              boxShadow: "0 0 12px 2px color-mix(in oklab, var(--color-ov-300) 55%, transparent)",
            }}
          />
        ))}
      </div>
    </div>
  );
}
=== ZielgruppenWahl
"use client";

import { useId, useState } from "react";
import Link from "next/link";
import { ArrowRight, Check, Factory, FolderUp, LineChart, MapPinned, Tractor } from "lucide-react";
import { cn } from "@/components/ui/cn";

/**
 * Weiche im Hero: Wer sind Sie? → passender Nutzen, drei Fakten, zwei Wege.
 * Echte Tabs (Pfeiltasten, aria-selected), serverseitig mit erster Gruppe gerendert.
 */
const GRUPPEN = [
  {
    id: "flaeche",
    label: "Fläche",
    lang: "Ich habe eine Fläche",
    icon: MapPinned,
    titel: "Planbare Pacht für 30 Jahre – ohne eigenes Risiko.",
    punkte: ["Kostenloser Flächencheck mit Pachtspanne", "Festpacht, indexiert oder mit Umsatzbeteiligung", "Rückbau vertraglich abgesichert"],
    primaer: { label: "Fläche prüfen", href: "/flaechencheck" },
    sekundaer: { label: "Pachtrechner", href: "/rechner/pacht" },
  },
  {
    id: "landwirt",
    label: "Landwirt",
    lang: "Ich bin Landwirt",
    icon: Tractor,
    titel: "Ernten und Strom erzeugen – auf demselben Acker.",
    punkte: ["Agri-PV nach DIN SPEC 91434", "Verpachten, selbst investieren oder beteiligen", "Direktzahlungen bleiben weitgehend erhalten"],
    primaer: { label: "Welcher Weg passt?", href: "/landwirte" },
    sekundaer: { label: "Agri-PV-Rechner", href: "/rechner/agri-pv" },
  },
  {
    id: "investor",
    label: "Investor",
    lang: "Ich möchte investieren",
    icon: LineChart,
    titel: "Geprüfte PV-Projekte – von Projektrechten bis Bestand.",
    punkte: ["Suchprofil mit automatischem Matching", "NDA und Datenraum digital", "Für Investoren kostenfrei"],
    primaer: { label: "Zur Projektbörse", href: "/projektboerse" },
    sekundaer: { label: "Renditerechner", href: "/rechner/solarpark" },
  },
  {
    id: "anbieter",
    label: "Anbieter",
    lang: "Ich biete ein Projekt an",
    icon: FolderUp,
    titel: "Ihr Projekt vor den richtigen Käufern im DACH-Raum.",
    punkte: ["Qualitätsprüfung vor Veröffentlichung", "Vertraulich bis zur NDA-Freigabe", "Provision nur bei Abschluss"],
    primaer: { label: "Projekt anbieten", href: "/projektboerse/anbieten" },
    sekundaer: { label: "Projekt bewerten", href: "/rechner/projektbewertung" },
  },
  {
    id: "unternehmen",
    label: "Firma",
    lang: "Ich brauche günstigen Strom",
    icon: Factory,
    titel: "Reststrom gemeinsam einkaufen – statt allein zu zahlen.",
    punkte: ["Bündelung im virtuellen Kraftwerk", "Solarstrom aus Parks der Gruppe", "Passt zu Ihrer PV und Ihrem Speicher"],
    primaer: { label: "Ersparnis berechnen", href: "/rechner/reststrom" },
    sekundaer: { label: "So funktioniert der Pool", href: "/reststrom" },
  },
];

export default function ZielgruppenWahl() {
  const basis = useId();
  const [aktiv, setAktiv] = useState(0);
  const g = GRUPPEN[aktiv];

  function taste(e) {
    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
    e.preventDefault();
    const n = (aktiv + (e.key === "ArrowRight" ? 1 : GRUPPEN.length - 1)) % GRUPPEN.length;
    setAktiv(n);
    document.getElementById(`${basis}-tab-${n}`)?.focus();
  }

  return (
    <div className="ov-glass rounded-[2rem] p-3 shadow-2xl sm:p-4">
      <p className="px-3 pb-3 pt-2 text-[12px] font-semibold uppercase tracking-[0.16em] text-white/60">Wer sind Sie?</p>
      <div role="tablist" aria-label="Zielgruppe wählen" onKeyDown={taste} className="grid grid-cols-5 gap-1 rounded-2xl bg-navy-950/60 p-1">
        {GRUPPEN.map((x, i) => {
          const an = i === aktiv;
          return (
            <button
              key={x.id}
              id={`${basis}-tab-${i}`}
              role="tab"
              type="button"
              aria-selected={an}
              aria-controls={`${basis}-panel`}
              tabIndex={an ? 0 : -1}
              onClick={() => setAktiv(i)}
              className={cn(
                "flex min-h-[64px] min-w-0 flex-col items-center justify-center gap-1.5 rounded-xl px-0.5 py-2 text-[11px] font-semibold transition-all duration-300 sm:text-[12.5px]",
                an ? "bg-white text-navy-900 shadow-lg" : "text-white/70 hover:bg-white/10 hover:text-white"
              )}
            >
              <x.icon aria-hidden="true" className={cn("h-5 w-5", an ? "text-ov-600" : "")} />
              <span className="leading-none">{x.label}</span>
            </button>
          );
        })}
      </div>

      <div id={`${basis}-panel`} role="tabpanel" aria-labelledby={`${basis}-tab-${aktiv}`} key={g.id} className="ov-tab-panel rounded-3xl bg-white p-6 text-ink-900 sm:p-7 mt-3">
        <p className="text-[13px] font-semibold text-ov-700">{g.lang}</p>
        <p className="mt-2 font-display text-[clamp(1.3rem,1.1rem+0.6vw,1.6rem)] font-extrabold leading-tight tracking-tight">{g.titel}</p>
        <ul className="mt-5 space-y-2.5">
          {g.punkte.map((p) => (
            <li key={p} className="flex items-start gap-2.5 text-[15px] text-ink-700">
              <span className="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-ov-500 text-white">
                <Check aria-hidden="true" className="h-3 w-3" strokeWidth={3} />
              </span>
              {p}
            </li>
          ))}
        </ul>
        <div className="mt-6 flex flex-col gap-2.5 sm:flex-row">
          <Link href={g.primaer.href} className="group inline-flex h-12 items-center sm:flex-1 justify-center gap-2 rounded-full bg-ov-600 px-5 text-[15px] font-semibold text-white shadow-[0_8px_24px_-8px_rgba(102,153,51,0.65)] transition-colors hover:bg-ov-700">
            {g.primaer.label}
            <ArrowRight aria-hidden="true" className="h-4 w-4 transition-transform group-hover:translate-x-1" />
          </Link>
          <Link href={g.sekundaer.href} className="inline-flex h-12 items-center justify-center rounded-full px-5 sm:flex-1 text-[15px] font-semibold text-ink-900 ring-1 ring-inset ring-ink-200 transition-colors hover:bg-ink-50">
            {g.sekundaer.label}
          </Link>
        </div>
      </div>
    </div>
  );
}
=== Vertrauensleiste
import { Factory, Hammer, Landmark, MapPinned, SunMedium } from "lucide-react";
import Stagger from "@/components/ui/Stagger";
import { GESELLSCHAFT, KENNZAHLEN } from "@/data/site";

/**
 * Vertrauensleiste direkt unter dem Hero.
 * Nur belegte Fakten (siehe docs/BRIEFING.md „Unternehmen“) – keine Kundenlogos,
 * keine Auszeichnungen, keine erfundenen Kennzahlen.
 */
const FAKTEN = [
  { icon: Factory, titel: "ÖKOVOLT Gruppe", text: `Solarkraftwerke seit ${KENNZAHLEN.gruppeGegruendet}` },
  { icon: SunMedium, titel: "Eigene Solarparks", text: "im Betrieb seit 2012" },
  { icon: Hammer, titel: "Eigene Rammtechnik", text: "Fundamente aus der Gruppe" },
  { icon: MapPinned, titel: "DE · AT · CH", text: "Projekte im gesamten DACH-Raum" },
  { icon: Landmark, titel: GESELLSCHAFT.register, text: GESELLSCHAFT.gericht.replace("Landesgericht", "LG") },
];

export default function Vertrauensleiste() {
  return (
    <section aria-label="Fakten zur ÖkoInvest GmbH" className="border-b border-ink-100 bg-white">
      <div className="ov-container">
        <Stagger
          as="ul"
          schritt={70}
          className="grid grid-cols-2 gap-x-4 gap-y-5 py-7 sm:grid-cols-3 md:py-8 lg:grid-cols-5 lg:gap-0"
        >
          {FAKTEN.map((f, i) => (
            <li
              key={f.titel}
              className={`flex items-center gap-3 ${i === FAKTEN.length - 1 ? "col-span-2 sm:col-span-1" : ""} lg:justify-center lg:px-4 ${i > 0 ? "lg:border-l lg:border-ink-100" : ""}`}
            >
              <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-ov-50 text-ov-600">
                <f.icon aria-hidden="true" className="h-[18px] w-[18px]" strokeWidth={1.9} />
              </span>
              <span className="min-w-0">
                <span className="block font-display text-[14.5px] font-bold leading-tight text-ink-900">{f.titel}</span>
                <span className="mt-0.5 block text-[12.5px] leading-snug text-ink-500">{f.text}</span>
              </span>
            </li>
          ))}
        </Stagger>
      </div>
    </section>
  );
}
=== Werttreppe
import { PHASEN } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";

/**
 * Werttreppe eines Freiflächenprojekts: Kaufpreisspanne je kWp nach
 * Entwicklungsphase (ohne Bestand – der liegt eine Größenordnung höher und
 * würde die Skala sprengen; er steht als Fußnote darunter).
 * Reine Server-Komponente, Balken in CSS, Werte aus markt.js.
 *
 * Aufbau je Phase: Name + Risiko-Meter + Spanne in einer Zeile, darunter die
 * Spannen-Leiste auf einer gemeinsamen €-Skala mit Hilfslinien. So bleibt die
 * Beschriftung auch mobil vollständig lesbar (nie im Balken abgeschnitten).
 */
const RISIKO_STUFE = { "sehr hoch": 5, hoch: 4, "mittel–hoch": 3, mittel: 2, gering: 1, "sehr gering": 0 };

export default function Werttreppe() {
  const stufen = PHASEN.filter((p) => p.id !== "cod");
  const bestand = PHASEN.find((p) => p.id === "cod");
  const max = Math.max(...stufen.map((p) => p.preisProKwp.max));
  const skala = Math.ceil(max / 50) * 50;
  const ticks = Array.from({ length: skala / 50 + 1 }, (_, i) => i * 50);

  return (
    <figure className="relative overflow-hidden rounded-[2rem] bg-white p-5 shadow-e3 ring-1 ring-ink-200/70 sm:p-7 md:p-8">
      <div aria-hidden="true" className="pointer-events-none absolute -right-24 -top-24 h-56 w-56 rounded-full bg-ov-100/70 blur-3xl" />
      <figcaption className="relative">
        <p className="text-[12px] font-semibold uppercase tracking-[0.16em] text-ov-700">Orientierung für Käufer und Verkäufer</p>
        <div className="mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1">
          <span className="font-display text-[20px] font-extrabold tracking-tight text-ink-900">Projektwert nach Phase</span>
          <span className="text-[12.5px] text-ink-500">Kaufpreis je kWp, Spanne DACH</span>
        </div>
      </figcaption>

      <ol className="relative mt-7 space-y-5">
        {stufen.map((p, i) => {
          const links = (p.preisProKwp.min / skala) * 100;
          const breite = ((p.preisProKwp.max - p.preisProKwp.min) / skala) * 100;
          const stufe = RISIKO_STUFE[p.risiko];
          return (
            <li key={p.id}>
              <div className="flex items-end justify-between gap-3">
                <div className="min-w-0">
                  <p className="flex items-center gap-2 text-[14.5px] font-semibold leading-tight text-ink-900">
                    <span className="ov-num flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-ink-100 text-[10.5px] font-bold text-ink-600">{i + 1}</span>
                    <span className="truncate">{p.kurz}</span>
                  </p>
                  <p className="mt-1 flex items-center gap-2 pl-7 text-[12px] text-ink-500">
                    {stufe !== undefined && (
                      <span aria-hidden="true" className="flex items-end gap-[2px]">
                        {[1, 2, 3, 4, 5].map((n) => (
                          <span key={n} className={`w-[3px] rounded-full ${n <= stufe ? "bg-sun-500" : "bg-ink-200"}`} style={{ height: `${4 + n * 1.6}px` }} />
                        ))}
                      </span>
                    )}
                    Risiko {p.risiko}
                  </p>
                </div>
                <p className="ov-num shrink-0 whitespace-nowrap font-display text-[15px] font-bold text-ink-900">
                  {fmt(p.preisProKwp.min)}–{fmt(p.preisProKwp.max)} <span className="text-[12px] font-semibold text-ink-500">€/kWp</span>
                </p>
              </div>
              <div aria-hidden="true" className="relative mt-2.5 h-3 rounded-full bg-ink-100/80">
                {ticks.slice(1, -1).map((t) => (
                  <span key={t} className="absolute inset-y-0 w-px bg-white" style={{ left: `${(t / skala) * 100}%` }} />
                ))}
                <span
                  className="ov-balken-x absolute inset-y-0 rounded-full bg-gradient-to-r from-ov-300 to-ov-600 shadow-[0_0_0_3px_rgba(255,255,255,0.9)]"
                  style={{ left: `${links}%`, width: `${breite}%`, "--i": i, opacity: 0.6 + (i / (stufen.length - 1)) * 0.4 }}
                />
              </div>
            </li>
          );
        })}
      </ol>

      {/* gemeinsame Skala */}
      <div aria-hidden="true" className="relative mt-3 h-4 text-[11px] text-ink-400">
        {ticks.map((t, i) => (
          <span
            key={t}
            className="ov-num absolute"
            style={i === 0 ? { left: 0 } : i === ticks.length - 1 ? { right: 0 } : { left: `${(t / skala) * 100}%`, transform: "translateX(-50%)" }}
          >
            {t} €
          </span>
        ))}
      </div>

      <div className="relative mt-6 flex gap-3 rounded-2xl bg-sand-50 p-4 ring-1 ring-ink-200/60">
        <span aria-hidden="true" className="mt-0.5 h-8 w-1 shrink-0 rounded-full bg-gradient-to-b from-navy-500 to-navy-800" />
        <p className="text-[12.5px] leading-relaxed text-ink-600">
          <span className="font-semibold text-ink-900">Bestandsanlagen (in Betrieb)</span> werden nach Ertragswert gehandelt, typischerweise{" "}
          <span className="ov-num font-semibold text-ink-900">{fmt(bestand.preisProKwp.min)}–{fmt(bestand.preisProKwp.max)} €</span> je kWp.
          Orientierungswerte – Netzanschluss, Tarif und Standort verschieben die Spanne deutlich.
        </p>
      </div>
    </figure>
  );
}
=== Kreislauf
/**
 * Die Wertschöpfungskette als Kreislauf: Fläche → Projekt → Kapital → Strom
 * → (Pacht, Rendite, günstiger Strom fließen zurück). Dekorative Inline-SVG
 * im Markenstil; die Aussage steht zusätzlich als Text daneben (aria-hidden).
 */
export default function Kreislauf() {
  const knoten = [
    { x: 200, y: 54, titel: "Fläche", sub: "Eigentümer & Landwirte" },
    { x: 346, y: 200, titel: "Projekt", sub: "Entwicklung & Börse" },
    { x: 200, y: 346, titel: "Kapital", sub: "Investoren & Bürger" },
    { x: 54, y: 200, titel: "Strom", sub: "Mittelstand & Gemeinden" },
  ];
  return (
    <svg viewBox="0 0 400 400" className="h-auto w-full" aria-hidden="true">
      <defs>
        <linearGradient id="kl-ring" x1="0" x2="1" y1="0" y2="1">
          <stop offset="0" stopColor="#8cba58" />
          <stop offset="1" stopColor="#436621" />
        </linearGradient>
        <marker id="kl-pfeil" viewBox="0 0 10 10" refX="6" refY="5" markerWidth="7" markerHeight="7" orient="auto">
          <path d="M0 0 L10 5 L0 10 z" fill="#669933" />
        </marker>
      </defs>
      <circle cx="200" cy="200" r="148" fill="none" stroke="#e6f1d8" strokeWidth="26" />
      <circle cx="200" cy="200" r="148" fill="none" stroke="url(#kl-ring)" strokeWidth="3" strokeDasharray="6 10" />
      {/* Pfeile zwischen den Knoten */}
      {[
        "M258 70 A148 148 0 0 1 330 142",
        "M330 258 A148 148 0 0 1 258 330",
        "M142 330 A148 148 0 0 1 70 258",
        "M70 142 A148 148 0 0 1 142 70",
      ].map((d) => (
        <path key={d} d={d} fill="none" stroke="#669933" strokeWidth="3" strokeLinecap="round" markerEnd="url(#kl-pfeil)" />
      ))}
      {/* Mitte */}
      <circle cx="200" cy="200" r="74" fill="#03122b" />
      <circle cx="200" cy="200" r="74" fill="none" stroke="#669933" strokeOpacity="0.45" strokeWidth="1.5" />
      <text x="200" y="192" textAnchor="middle" fontFamily="var(--font-manrope)" fontWeight="800" fontSize="20" fill="#fff">ÖkoInvest</text>
      <text x="200" y="215" textAnchor="middle" fontFamily="var(--font-inter)" fontWeight="600" fontSize="11.5" fill="#aed083">Plattform</text>
      {knoten.map((k) => (
        <g key={k.titel}>
          <circle cx={k.x} cy={k.y} r="50" fill="#fff" stroke="#cde3b1" strokeWidth="2" />
          <text x={k.x} y={k.y - 6} textAnchor="middle" fontFamily="var(--font-manrope)" fontWeight="800" fontSize="16" fill="#151a24">{k.titel}</text>
          {k.sub.split(" & ").map((zeile, i, alle) => (
            <text key={zeile} x={k.x} y={k.y + 11 + i * 11} textAnchor="middle" fontFamily="var(--font-inter)" fontSize="9" fill="#6b7486">
              {zeile}{i < alle.length - 1 ? " &" : ""}
            </text>
          ))}
        </g>
      ))}
    </svg>
  );
}
=== Sprungnavigation
// Sprungnavigation der Startseite (UX-Audit P2-7): kompakte Chips direkt unter dem Hero.
// Mobil klebt die Leiste beim Scrollen unter dem Seitenkopf (68 px), ab md steht sie normal im Fluss.
// Server-Komponente, reine Anker-Links – funktioniert ohne JavaScript.

const ZIELE = [
  { id: "loesungen", label: "Lösungen" },
  { id: "boerse", label: "Börse" },
  { id: "energie", label: "Energie" },
  { id: "tools", label: "Tools" },
  { id: "faq", label: "FAQ" },
];

export default function Sprungnavigation() {
  return (
    <nav
      aria-label="Auf dieser Seite"
      className="sticky top-[68px] z-30 border-b border-ink-200/70 bg-white/90 backdrop-blur-xl backdrop-saturate-150 md:static md:bg-white md:backdrop-blur-none"
    >
      <ul className="ov-container flex gap-2 overflow-x-auto py-2.5 [scrollbar-width:none] md:justify-center md:py-3">
        {ZIELE.map((z) => (
          <li key={z.id} className="shrink-0">
            <a
              href={`#${z.id}`}
              className="flex min-h-10 items-center rounded-full bg-sand-50 px-4 text-[14px] font-semibold text-ink-800 ring-1 ring-ink-200/70 transition-colors hover:bg-ov-50 hover:text-ov-800 hover:ring-ov-200 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ov-500"
            >
              {z.label}
            </a>
          </li>
        ))}
      </ul>
    </nav>
  );
}

import Link from "next/link";
import { ArrowUpRight, Phone, Calculator, ShieldCheck, Clock, BadgeCheck } from "lucide-react";
import { KONTAKT } from "@/data/site";
import { cn } from "./cn";
import Button from "./Button";
