@layer components {
  .ov-spotlight { position: relative; isolation: isolate; } /* Utilities (absolute …) dürfen überschreiben */
}
.ov-spot-licht {
  position: absolute;
  inset: 0;
  z-index: 1;
  border-radius: inherit;
  overflow: hidden;
  pointer-events: none;
}
.ov-spot-licht::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: var(--ov-spot-groesse, 440px);
  height: var(--ov-spot-groesse, 440px);
  margin: calc(var(--ov-spot-groesse, 440px) / -2) 0 0 calc(var(--ov-spot-groesse, 440px) / -2);
  border-radius: 9999px;
  background: radial-gradient(closest-side, var(--ov-spot-farbe, rgba(102, 153, 51, 0.13)), transparent);
  transform: translate3d(var(--ov-mx, -999px), var(--ov-my, -999px), 0);
  opacity: 0;
  transition: opacity 320ms var(--ov-ease-out);
  will-change: transform;
}
.ov-spotlight[data-ton="dunkel"] { --ov-spot-farbe: rgba(174, 208, 131, 0.16); }
.ov-spotlight.ov-zeiger-an .ov-spot-licht::before { opacity: 1; }
@media (hover: none), (pointer: coarse), (prefers-reduced-motion: reduce) {
  .ov-spot-licht { display: none; }
}

