cd ~/claude-browser && O=/c/Users/SALEAD~1/AppData/Local/Temp/claude/c--Users-SALEADMIN-Downloads-Oekoinvest-Web/3140c08a-2721-4ee9-a47f-9fce6660cd23/scratchpad/wf4/start && cat > $O/probe.mjs <<'EOF'
import { chromium } from "playwright";
const O = process.argv[2];
const b = await chromium.launch();
const ctx = await b.newContext({ viewport: { width: 1440, height: 900 } });
await ctx.addInitScript(() => { try { localStorage.setItem("cookie-consent", "necessary"); } catch {} });
const p = await ctx.newPage();
const err = []; p.on("console", (m) => m.type() === "error" && err.push(m.text()));
await p.goto("http://localhost:3100/", { waitUntil: "load", timeout: 180000 });
await p.locator("button", { hasText: "Nur notwendige" }).first().click({ timeout: 1500 }).catch(() => {});
await p.waitForTimeout(800);
await p.getByRole("tab", { name: "Investor" }).click();
await p.waitForTimeout(600);
await p.screenshot({ path: O + "/p-tab-investor.png", clip: { x: 780, y: 250, width: 560, height: 600 } });
await p.getByRole("tab", { name: "Investor" }).press("End");
await p.waitForTimeout(600);
await p.screenshot({ path: O + "/p-tab-firma.png", clip: { x: 780, y: 250, width: 560, height: 600 } });
await p.getByRole("tab", { name: "Investor" }).click();
// CTA band
const band = p.locator("section").filter({ hasText: "Direkt zum passenden Weg" }).last();
await band.scrollIntoViewIfNeeded(); await p.waitForTimeout(1200);
console.log("CTA:", await band.locator("h2").innerText(), "|", await band.locator("a").first().getAttribute("href"));
await band.screenshot({ path: O + "/p-cta.png" });
// hover card
await p.locator("[data-kl=kapital]").scrollIntoViewIfNeeded(); await p.waitForTimeout(2500);
await p.locator("[data-kl=kapital]").hover(); await p.waitForTimeout(500);
await p.screenshot({ path: O + "/p-hover.png" });
console.log("Fehler", err);
await b.close();
EOF
node $O/probe.mjs $O 2>&1 | tail -5

